package solution

import "testing"

func TestStackBasic(t *testing.T) {
	s := &Stack{}
	if !s.IsEmpty() { t.Fatal("new stack should be empty") }
	s.Push(1); s.Push(2); s.Push(3)
	if v, ok := s.Peek(); !ok || v != 3 { t.Fatalf("Peek: got %d,%v want 3,true", v, ok) }
	if v, ok := s.Pop(); !ok || v != 3 { t.Fatalf("Pop: got %d,%v want 3,true", v, ok) }
	if v, ok := s.Pop(); !ok || v != 2 { t.Fatalf("Pop: got %d,%v want 2,true", v, ok) }
	if s.IsEmpty() { t.Fatal("stack should still have 1 element") }
}

func TestStackEmpty(t *testing.T) {
	s := &Stack{}
	if _, ok := s.Pop(); ok { t.Error("Pop on empty should return false") }
	if _, ok := s.Peek(); ok { t.Error("Peek on empty should return false") }
}

